-- ===== STRUKTUR TABEL =====
CREATE TABLE kategori (
    id      INT PRIMARY KEY,
    nama    VARCHAR(50) NOT NULL
);

CREATE TABLE produk (
    id           INT PRIMARY KEY,
    nama         VARCHAR(100)   NOT NULL,
    kategori_id  INT            REFERENCES kategori(id),
    harga        DECIMAL(12,2)  NOT NULL,
    stok         INT            NOT NULL DEFAULT 0
);

CREATE TABLE pelanggan (
    id              INT PRIMARY KEY,
    nama            VARCHAR(100) NOT NULL,
    email           VARCHAR(100) UNIQUE,
    kota            VARCHAR(50),
    tanggal_daftar  DATE         NOT NULL
);

CREATE TABLE pesanan (
    id            INT PRIMARY KEY,
    pelanggan_id  INT         REFERENCES pelanggan(id),
    tanggal       DATE        NOT NULL,
    status        VARCHAR(20) NOT NULL     -- 'baru','dikirim','selesai','batal'
);

CREATE TABLE detail_pesanan (
    pesanan_id    INT           REFERENCES pesanan(id),
    produk_id     INT           REFERENCES produk(id),
    qty           INT           NOT NULL,
    harga_satuan  DECIMAL(12,2) NOT NULL,
    PRIMARY KEY (pesanan_id, produk_id)
);

-- menambah kolom
ALTER TABLE produk ADD COLUMN berat_gram INT;

