SELECT * FROM pelanggan WHERE email IS NOT NULL;

-- NULL dalam perhitungan menular: hasilnya ikut NULL
SELECT 100 + NULL;          -- NULL, bukan 100

-- COALESCE: ambil nilai pertama yang bukan NULL
SELECT nama, COALESCE(email, 'tidak ada email') AS kontak FROM pelanggan;

-- NULLIF: jadikan NULL bila dua nilai sama (berguna mencegah bagi nol)
