-- 5 produk termahal
-- PostgreSQL, MySQL, SQLite
SELECT nama, harga FROM produk ORDER BY harga DESC LIMIT 5;
SELECT TOP 5 nama, harga FROM produk ORDER BY harga DESC;           -- SQL Server
-- standar SQL & Oracle 12c+
SELECT nama, harga FROM produk ORDER BY harga DESC FETCH FIRST 5 ROWS ONLY;

-- paginasi: halaman ke-3 dengan 10 baris per halaman
SELECT nama FROM produk ORDER BY id LIMIT 10 OFFSET 20;
SELECT nama FROM produk ORDER BY id OFFSET 20 ROWS FETCH NEXT 10 ROWS ONLY;  -- SQL Server

-- penggabungan teks
-- standar SQL, PostgreSQL, SQLite, Oracle
SELECT nama || ' - ' || kota AS label FROM pelanggan;
SELECT CONCAT(nama, ' - ', kota) FROM pelanggan;            -- MySQL, SQL Server, PostgreSQL

-- membersihkan data saat impor
SELECT TRIM(LOWER(email)) AS email_bersih FROM pelanggan;

-- pelanggan yang pernah memesan
SELECT nama FROM pelanggan
WHERE  id IN (SELECT pelanggan_id FROM pesanan);

-- produk dari kategori minuman
SELECT nama FROM produk
WHERE  kategori_id IN (SELECT id FROM kategori WHERE nama = 'Minuman');

-- EXISTS: berhenti mencari begitu satu kecocokan ditemukan
SELECT nama FROM pelanggan pl
WHERE  EXISTS (SELECT 1 FROM pesanan ps WHERE ps.pelanggan_id = pl.id);

-- NOT EXISTS: aman terhadap NULL, tidak seperti NOT IN
SELECT nama FROM pelanggan pl
WHERE  NOT EXISTS (SELECT 1 FROM pesanan ps WHERE ps.pelanggan_id = pl.id);

