-- PostgreSQL: function yang mengembalikan nilai
CREATE OR REPLACE FUNCTION total_pesanan(p_pesanan_id INT)
RETURNS DECIMAL AS $$
    SELECT COALESCE(SUM(qty * harga_satuan), 0)
    FROM   detail_pesanan
    WHERE  pesanan_id = p_pesanan_id;
$$ LANGUAGE SQL;

SELECT nama, total_pesanan(id) FROM pesanan p JOIN ...;

-- procedure dengan logika prosedural
CREATE OR REPLACE PROCEDURE kurangi_stok(p_produk_id INT, p_qty INT)
LANGUAGE plpgsql AS $$
BEGIN
    IF (SELECT stok FROM produk WHERE id = p_produk_id) < p_qty THEN
        RAISE EXCEPTION 'Stok tidak mencukupi untuk produk %', p_produk_id;
    END IF;

    UPDATE produk SET stok = stok - p_qty WHERE id = p_produk_id;
END;
$$;

CALL kurangi_stok(1, 2);

-- mencatat perubahan harga secara otomatis
CREATE TABLE log_harga (
    id SERIAL PRIMARY KEY, produk_id INT,
    harga_lama DECIMAL(12,2), harga_baru DECIMAL(12,2),
    diubah_pada TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE OR REPLACE FUNCTION catat_perubahan_harga()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD.harga IS DISTINCT FROM NEW.harga THEN
        INSERT INTO log_harga (produk_id, harga_lama, harga_baru)
        VALUES (OLD.id, OLD.harga, NEW.harga);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_harga
AFTER UPDATE ON produk
FOR EACH ROW EXECUTE FUNCTION catat_perubahan_harga();

